def restore_reviewed_source(name,data):
    if type(name) is not str or name not in _REVIEWED:raise ValueError('Unreviewed source name')
    if type(data) is not bytes:raise TypeError('Exact source bytes required')
    b=data.replace(b'\r\n',b'\n');t=_REVIEWED[name];digest=hashlib.sha256(b).hexdigest()
    if digest==t['beforeSha256']:
        if len(b)!=t['beforeBytes']:raise ValueError('Preimage extent mismatch')
        return b
    if digest!=t['afterSha256'] or len(b)!=t['afterBytes']:raise ValueError('Unreviewed whole source')
    out=[];cursor=0
    for start,end,expected,replacement in t['edits']:
        if start<cursor or end<start or b[start:end]!=base64.b64decode(expected):raise ValueError('Reviewed reverse patch mismatch')
        out.extend((b[cursor:start],base64.b64decode(replacement)));cursor=end
    out.append(b[cursor:]);result=b''.join(out)
    if len(result)!=t['beforeBytes'] or hashlib.sha256(result).hexdigest()!=t['beforeSha256']:raise ValueError('Exact restored preimage mismatch')
    return result
